// Usage: npm run db:sql   — writes supabase/seed.sql, a paste-able SQL version of the synthetic dataset.
import fs from "node:fs";
import { TABLES, generateDemoDataset, type Row } from "../lib/demo/generate";

const lit = (v: string | number | null) => (v === null ? "null" : typeof v === "number" ? String(v) : `'${v.replace(/'/g, "''")}'`);
const data = generateDemoDataset();
const out: string[] = [
  "-- Synthetic demo data for Benchmark Hospital. Generated by `npm run db:sql` — do not edit by hand.",
  "-- Wipes the demo tables first, so run it on a fresh project (or when you want to reset to demo data).",
  "begin;",
  `truncate ${TABLES.map((t) => t.name).join(", ")} restart identity cascade;`,
];
for (const t of TABLES) {
  const rows: Row[] = data[t.name];
  const cols = Object.keys(rows[0]);
  for (let i = 0; i < rows.length; i += 200) {
    const values = rows.slice(i, i + 200).map((r) => `(${cols.map((c) => lit(r[c])).join(",")})`);
    out.push(`insert into ${t.name} (${cols.join(",")}) values\n${values.join(",\n")};`);
  }
}
out.push(
  "-- explicit ids were used for sites/departments: move the identity sequences past them",
  "select reset_identity_sequences();",
  "commit;",
);
fs.writeFileSync("supabase/seed.sql", out.join("\n") + "\n");
console.log(`Wrote supabase/seed.sql (${Object.values(data).reduce((n, r) => n + r.length, 0)} rows).`);
